cd /work/workspace/documents && python3 << 'EOF'
import csv, json
from decimal import Decimal as D
feb, names = {}, {}
for r in csv.DictReader(open('trial_balance_2026-02-28.csv')):
    feb[r['account']] = (D(r['debit']) if r['debit'] else D(0)) - (D(r['credit']) if r['credit'] else D(0))
    names[r['account']] = r['name']
for r in csv.DictReader(open('chart_of_accounts.csv')):
    names.setdefault(r['account'], D(0))
bal = dict(feb)
for r in csv.DictReader(open('general_ledger_2026-03.csv')):
    if r['date'] >= '2026-03-01':
        bal[r['account']] = bal.get(r['account'], D(0)) + (D(r['debit']) if r['debit'] else D(0)) - (D(r['credit']) if r['credit'] else D(0))
for m in [{'1000':'4312','2100':'-4312'},{'6700':'35','1000':'-35'},{'2000':'4860','5000':'-4860'},{'1300':'1150','6300':'-1150'},{'1300':'1188','6400':'-1188'}]:
    for a,v in m.items(): bal[a] = bal.get(a,D(0)) + D(v)
out = {"accounts": {a: {"debit": float(f"{v:.2f}") if v>0 else 0.00, "credit": float(f"{-v:.2f}") if v<0 else 0.00} for a,v in sorted(bal.items())}}
td = sum(x["debit"] for x in out["accounts"].values()); tc = sum(x["credit"] for x in out["accounts"].values())
assert round(td-tc,2)==0.00
out["totals"] = {"debits": round(td,2), "credits": round(tc,2)}
out["note"] = "Post-adjustment TB at 3/31/2026 = Feb 2/28 TB + March-dated GL activity (Feb-dated CH-7731 email-copy entry already sits in the 2/28 TB and is not reposted) + AJE-1..AJE-5 in adjusting_entries.json. Debits = credits = 424,932.07. Note: 1100 A/R (115,288.00) does NOT agree to the A/R aging subledger (49,850.00 after applying check #4471) — see open_items.md; no plug entry was made."
json.dump(out, open('/work/deliverable/trial_balance_2026-03-31.json','w'), indent=2)
print("debits", td, "credits", tc, "accounts", len(out["accounts"]))
EOF

